+const MAX_PORT = 65535;
+
+function parsePort(text: string, item: string): number {
+  if (!/^[0-9]+$/.test(text)) {
+    throw new Error(`Invalid port list item: "${item}"`);
+  }
+  const port = Number(text);
+  if (port < 1 || port > MAX_PORT) {
+    throw new Error(`Port out of range (1-${MAX_PORT}): "${item}"`);
+  }
+  return port;
+}
+
+function parseItem(raw: string): PortRange {
+  const item = raw.trim();
+  if (item === "") {
+    throw new Error("Empty item in port list");
+  }
+  const parts = item.split("-");
+  if (parts.length === 1) {
+    const port = parsePort(item, item);
+    return [port, port];
+  }
+  if (parts.length !== 2) {
+    throw new Error(`Invalid port list item: "${item}"`);
+  }
+  const from = parsePort(parts[0].trim(), item);
+  const to = parsePort(parts[1].trim(), item);
+  if (to < from) {
+    throw new Error(`Range end is below its start: "${item}"`);
+  }
+  return [from, to];
+}

